import { state as checkoutState, dispose as disposeCheckout } from '../../../../../src/store/checkout';
import { state as processorsState, dispose as disposeProcessors } from '../../../../../src/store/processors';
import { ScStripePaymentElement } from '../sc-stripe-payment-element';

describe('sc-stripe-payment-element', () => {
  beforeEach(() => {
    disposeCheckout();
    disposeProcessors();
  });

  describe('maybeApplyFilters', () => {
    let mockApplyFilters: jest.MockedFunction<any>;
    let originalWindow: Window;

    // Create a test instance of the maybeApplyFilters method
    // This mimics what the actual component does
    const maybeApplyFilters = function (options: any) {
      if (!window?.wp?.hooks?.applyFilters) return options;

      return {
        ...options,
        paymentMethodOrder: window.wp.hooks.applyFilters('surecart_stripe_payment_element_payment_method_order', [], checkoutState.checkout),
        wallets: window.wp.hooks.applyFilters('surecart_stripe_payment_element_wallets', {}, checkoutState.checkout),
        terms: window.wp.hooks.applyFilters('surecart_stripe_payment_element_terms', {}, checkoutState.checkout),
        fields: window.wp.hooks.applyFilters('surecart_stripe_payment_element_fields', options.fields ?? {}),
      };
    };

    beforeEach(() => {
      // Setup window object if it doesn't exist
      if (!(global as any).window) {
        (global as any).window = {};
      }

      // Store original window
      originalWindow = (global as any).window;

      // Reset window.wp before each test
      (global as any).window.wp = undefined;

      mockApplyFilters = jest.fn();
    });

    afterEach(() => {
      // Restore original window
      (global as any).window = originalWindow;
    });

    it('returns original options when window.wp is undefined', () => {
      const options = { fields: { test: 'value' }, other: 'data' };
      const result = maybeApplyFilters(options);

      expect(result).toBe(options);
      expect(result).toEqual(options);
    });

    it('returns original options when window.wp.hooks is undefined', () => {
      (global as any).window.wp = {};
      const options = { fields: { test: 'value' }, other: 'data' };
      const result = maybeApplyFilters(options);

      expect(result).toBe(options);
      expect(result).toEqual(options);
    });

    it('returns original options when window.wp.hooks.applyFilters is undefined', () => {
      (global as any).window.wp = { hooks: {} };
      const options = { fields: { test: 'value' }, other: 'data' };
      const result = maybeApplyFilters(options);

      expect(result).toBe(options);
      expect(result).toEqual(options);
    });

    it('applies filters when wp.hooks.applyFilters is available', () => {
      // Mock the checkout state
      const mockCheckout = { id: 'test-checkout' };
      checkoutState.checkout = mockCheckout as any;

      // Setup mock for applyFilters
      mockApplyFilters.mockImplementation((filterName, defaultValue) => {
        switch (filterName) {
          case 'surecart_stripe_payment_element_payment_method_order':
            return ['card', 'paypal'];
          case 'surecart_stripe_payment_element_wallets':
            return { applePay: 'auto', googlePay: 'auto' };
          case 'surecart_stripe_payment_element_terms':
            return { card: 'auto' };
          case 'surecart_stripe_payment_element_fields':
            return { billingDetails: { email: 'never' } };
          default:
            return defaultValue;
        }
      });

      (global as any).window.wp = { hooks: { applyFilters: mockApplyFilters } };

      const options = { fields: { test: 'value' }, other: 'data' };
      const result = maybeApplyFilters(options);

      // Verify filters were called with correct arguments
      expect(mockApplyFilters).toHaveBeenCalledTimes(4);
      expect(mockApplyFilters).toHaveBeenCalledWith('surecart_stripe_payment_element_payment_method_order', [], mockCheckout);
      expect(mockApplyFilters).toHaveBeenCalledWith('surecart_stripe_payment_element_wallets', {}, mockCheckout);
      expect(mockApplyFilters).toHaveBeenCalledWith('surecart_stripe_payment_element_terms', {}, mockCheckout);
      expect(mockApplyFilters).toHaveBeenCalledWith('surecart_stripe_payment_element_fields', { test: 'value' });

      // Verify the result has the filtered values
      expect(result).toEqual({
        fields: { billingDetails: { email: 'never' } },
        other: 'data',
        paymentMethodOrder: ['card', 'paypal'],
        wallets: { applePay: 'auto', googlePay: 'auto' },
        terms: { card: 'auto' },
      });

      // Verify original options were not mutated (immutability check)
      expect(options).toEqual({ fields: { test: 'value' }, other: 'data' });
      expect(result).not.toBe(options);
    });

    it('handles undefined options.fields gracefully', () => {
      checkoutState.checkout = {} as any;
      mockApplyFilters.mockReturnValue({});
      (global as any).window.wp = { hooks: { applyFilters: mockApplyFilters } };

      const options = { other: 'data' };
      const result = maybeApplyFilters(options);

      // Verify the fields filter was called with empty object when fields is undefined
      expect(mockApplyFilters).toHaveBeenCalledWith('surecart_stripe_payment_element_fields', {});

      expect(result).toHaveProperty('fields', {});
    });

    it('preserves all original properties when applying filters', () => {
      checkoutState.checkout = {} as any;
      mockApplyFilters.mockImplementation((_, defaultValue) => defaultValue);
      (global as any).window.wp = { hooks: { applyFilters: mockApplyFilters } };

      const options = {
        fields: { test: 'value' },
        existingProp1: 'value1',
        existingProp2: { nested: 'object' },
        existingProp3: [1, 2, 3],
      };

      const result = maybeApplyFilters(options);

      // All original properties should be preserved
      expect(result.existingProp1).toBe('value1');
      expect(result.existingProp2).toEqual({ nested: 'object' });
      expect(result.existingProp3).toEqual([1, 2, 3]);

      // New properties should be added
      expect(result).toHaveProperty('paymentMethodOrder');
      expect(result).toHaveProperty('wallets');
      expect(result).toHaveProperty('terms');
      expect(result).toHaveProperty('fields');
    });
  });

  describe('elements config filter', () => {
    let mockApplyFilters: jest.MockedFunction<any>;
    let originalWindow: Window;

    // Mimics the filter application at the end of getElementsConfig().
    const applyElementsConfigFilter = function (config: any) {
      if (!window?.wp?.hooks?.applyFilters) return config;

      return window.wp.hooks.applyFilters('surecart_stripe_payment_element_elements_config', config, checkoutState.checkout) ?? config;
    };

    beforeEach(() => {
      if (!(global as any).window) {
        (global as any).window = {};
      }
      originalWindow = (global as any).window;
      (global as any).window.wp = undefined;
      mockApplyFilters = jest.fn();
    });

    afterEach(() => {
      (global as any).window = originalWindow;
    });

    it('returns original config when wp.hooks.applyFilters is unavailable', () => {
      const config = { mode: 'payment', amount: 1000, currency: 'eur' };

      expect(applyElementsConfigFilter(config)).toBe(config);

      (global as any).window.wp = { hooks: {} };
      expect(applyElementsConfigFilter(config)).toBe(config);
    });

    it('passes the config and checkout to the filter and returns the filtered value', () => {
      const mockCheckout = { id: 'test-checkout' };
      checkoutState.checkout = mockCheckout as any;

      const config = { mode: 'payment', amount: 1000, currency: 'eur' };
      const filtered = { ...config, paymentMethodTypes: ['card'] };
      mockApplyFilters.mockReturnValue(filtered);
      (global as any).window.wp = { hooks: { applyFilters: mockApplyFilters } };

      const result = applyElementsConfigFilter(config);

      expect(mockApplyFilters).toHaveBeenCalledWith('surecart_stripe_payment_element_elements_config', config, mockCheckout);
      expect(result).toEqual(filtered);
    });

    it('falls back to the original config when the filter returns a nullish value', () => {
      checkoutState.checkout = {} as any;
      mockApplyFilters.mockReturnValue(undefined);
      (global as any).window.wp = { hooks: { applyFilters: mockApplyFilters } };

      const config = { mode: 'setup' };
      expect(applyElementsConfigFilter(config)).toBe(config);
    });

    describe('getElementsConfig', () => {
      let originalGetComputedStyle: any;
      const getElementsConfig = () => ScStripePaymentElement.prototype.getElementsConfig.call({ el: {} });

      beforeEach(() => {
        originalGetComputedStyle = (global as any).getComputedStyle;
        (global as any).getComputedStyle = jest.fn(() => ({ getPropertyValue: () => '' }));
        checkoutState.checkout = { remaining_amount_due: 1000, currency: 'usd' } as any;
        (global as any).window.wp = { hooks: { applyFilters: mockApplyFilters } };
      });

      afterEach(() => {
        (global as any).getComputedStyle = originalGetComputedStyle;
      });

      it('always sends excludedPaymentMethodTypes so a dropped exclusion is cleared on update', () => {
        mockApplyFilters.mockImplementationOnce((_, config) => ({ ...config, excludedPaymentMethodTypes: ['cashapp'] })).mockImplementationOnce((_, config) => config);

        expect(getElementsConfig().excludedPaymentMethodTypes).toEqual(['cashapp']);
        expect(getElementsConfig().excludedPaymentMethodTypes).toEqual([]);
      });

      it('drops excludedPaymentMethodTypes when the filter sets an allowlist', () => {
        mockApplyFilters.mockImplementation((_, config) => ({ ...config, paymentMethodTypes: ['card'] }));

        const result = getElementsConfig();
        expect(result.paymentMethodTypes).toEqual(['card']);
        expect(result).not.toHaveProperty('excludedPaymentMethodTypes');
      });

      it('treats an empty allowlist as no allowlist', () => {
        mockApplyFilters.mockImplementation((_, config) => ({ ...config, paymentMethodTypes: [] }));

        const result = getElementsConfig();
        expect(result).not.toHaveProperty('paymentMethodTypes');
        expect(result.excludedPaymentMethodTypes).toEqual([]);
      });
    });
  });

  describe('createOrUpdateElements', () => {
    const makeElements = () => ({ update: jest.fn(), create: jest.fn(() => ({ mount: jest.fn() })), getElement: jest.fn(() => ({ on: jest.fn(), destroy: jest.fn() })) });

    it('rebuilds Elements when leaving allowlist mode, since update() cannot unset paymentMethodTypes', () => {
      checkoutState.checkout = { payment_method_required: true, status: 'draft' } as any;

      const first = makeElements();
      const second = makeElements();
      (processorsState.instances as any).stripe = { elements: jest.fn().mockReturnValueOnce(first).mockReturnValueOnce(second) };

      const configs = [{ paymentMethodTypes: ['card'] }, { excludedPaymentMethodTypes: [] }];
      const component: any = Object.create(ScStripePaymentElement.prototype);
      Object.assign(component, { container: {}, scPaymentInfoAdded: { emit: jest.fn() }, getElementsConfig: () => configs.shift(), maybeApplyFilters: (o: any) => o });

      component.createOrUpdateElements();
      const firstElement = component.element;
      component.createOrUpdateElements();

      expect(firstElement.destroy).toHaveBeenCalled();
      expect(first.update).not.toHaveBeenCalled();
      expect((processorsState.instances as any).stripe.elements).toHaveBeenLastCalledWith({ excludedPaymentMethodTypes: [] });
      expect(processorsState.instances.stripeElements).toBe(second);
    });

    it('stays responsive after Stripe rejects a filtered config', () => {
      checkoutState.checkout = { payment_method_required: true, status: 'draft' } as any;
      const elements = { update: jest.fn(() => { throw new Error('invalid'); }) };
      (processorsState.instances as any).stripe = {};
      (processorsState.instances as any).stripeElements = elements;

      const component: any = Object.create(ScStripePaymentElement.prototype);
      Object.assign(component, { getElementsConfig: () => ({ excludedPaymentMethodTypes: ['nope'] }) });

      expect(() => component.createOrUpdateElements()).toThrow('invalid');
      expect(component.isCreatingUpdatingStripeElement).toBe(false);
    });
  });
});
